const gate = {
  code: 42,
  read() {
    return this === undefined ? "lost" : this.code;
  },
};

const side = { code: 7, read: gate.read };

console.log((gate.read)());
console.log((gate.read || side.read)());
console.log((side.code > 5 ? side.read : gate.read)());
console.log(side["read"]());
